export type TaskDueFilter = 'TODAY' | 'OVERDUE' | 'THIS_WEEK' | 'NO_DUE_DATE';

export type TaskSort = 'CREATED_DESC' | 'CREATED_ASC' | 'DUE_DATE_ASC' | 'DUE_DATE_DESC';

